import { z } from "zod";

import {
  BOOKMARK_LIST_VIEWS,
  READING_STATES,
  SORT_ORDERS,
  type BookmarkInput,
  type PageMetadataRequest,
  type ReadingStateUpdate,
  type ResolvedBookmarkListQuery,
